import{_ as t,o as a,c as r,l as s,t as n,N as o}from"./chunks/framework.CMqbtke2.js";const b=JSON.parse('{"title":"md5sum | x-cmd man (man1) | compute and check MD5 message digest","titleTemplate":false,"description":"x-cmd man (man1 Manual Page) | md5sum - compute and check MD5 message digest","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"md5sum | x-cmd man (man1) | compute and check MD5 message digest"}],["meta",{"name":"og:description","content":"x-cmd man (man1 Manual Page) | md5sum - compute and check MD5 message digest"}]]},"headers":[],"params":{"isMan":true,"man":"md5sum","category":"man1","desc":"compute and check MD5 message digest"},"relativePath":"man1/md5sum.md","filePath":"man1/md5sum.md"}'),d={name:"man1/md5sum.md"},i={class:"visually-hidden"},l=o('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>md5sum - compute and check MD5 message digest</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>md5sum</strong> [<em>OPTION</em>]... [<em>FILE</em>]...</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Print or check MD5 (128-bit) checksums.</p><p>With no FILE, or when FILE is -, read standard input.</p><dl><dt><strong>-b</strong>, <strong>--binary</strong></dt><dd>read in binary mode</dd><dt><strong>-c</strong>, <strong>--check</strong></dt><dd>read checksums from the FILEs and check them</dd><dt><strong>--tag</strong></dt><dd>create a BSD-style checksum</dd><dt><strong>-t</strong>, <strong>--text</strong></dt><dd>read in text mode (default)</dd><dt><strong>-z</strong>, <strong>--zero</strong></dt><dd>end each output line with NUL, not newline, and disable file name escaping</dd></dl><h3 id="the-following-five-options-are-useful-only-when-verifying-checksums" tabindex="-1">The following five options are useful only when verifying checksums: <a class="header-anchor" href="#the-following-five-options-are-useful-only-when-verifying-checksums" aria-label="Permalink to &quot;The following five options are useful only when verifying checksums:&quot;">​</a></h3><dl><dt><strong>--ignore-missing</strong></dt><dd>don&#39;t fail or report status for missing files</dd><dt><strong>--quiet</strong></dt><dd>don&#39;t print OK for each successfully verified file</dd><dt><strong>--status</strong></dt><dd>don&#39;t output anything, status code shows success</dd><dt><strong>--strict</strong></dt><dd>exit non-zero for improperly formatted checksum lines</dd><dt><strong>-w</strong>, <strong>--warn</strong></dt><dd>warn about improperly formatted checksum lines</dd><dt><strong>--help</strong></dt><dd>display this help and exit</dd><dt><strong>--version</strong></dt><dd>output version information and exit</dd></dl><p>The sums are computed as described in RFC 1321. When checking, the input should be a former output of this program. The default mode is to print a line with: checksum, a space, a character indicating input mode (&#39;*&#39; for binary, &#39; &#39; for text or where binary is insignificant), and name for each FILE.</p><p>Note: There is no difference between binary mode and text mode on GNU systems.</p><h2 id="bugs" tabindex="-1">BUGS <a class="header-anchor" href="#bugs" aria-label="Permalink to &quot;BUGS&quot;">​</a></h2><p>Do not use the MD5 algorithm for security related purposes. Instead, use an SHA-2 algorithm, implemented in the programs <strong>sha224sum</strong>(1), <strong>sha256sum</strong>(1), <strong>sha384sum</strong>(1), <strong>sha512sum</strong>(1), or the BLAKE2 algorithm, implemented in <strong>b2sum</strong>(1)</p><h2 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h2><p>Written by Ulrich Drepper, Scott Miller, and David Madore.</p><h2 id="reporting-bugs" tabindex="-1">REPORTING BUGS <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to &quot;REPORTING BUGS&quot;">​</a></h2><p>GNU coreutils online help: &lt;<a href="https://www.gnu.org/software/coreutils/%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/\\</a>&gt; <br> Report any translation bugs to &lt;<a href="https://translationproject.org/team/%5C" target="_blank" rel="noreferrer">https://translationproject.org/team/\\</a>&gt;</p><h2 id="copyright" tabindex="-1">COPYRIGHT <a class="header-anchor" href="#copyright" aria-label="Permalink to &quot;COPYRIGHT&quot;">​</a></h2><p>Copyright © 2023 Free Software Foundation, Inc. License GPLv3+: GNU GPL version 3 or later &lt;<a href="https://gnu.org/licenses/gpl.html%5C" target="_blank" rel="noreferrer">https://gnu.org/licenses/gpl.html\\</a>&gt;. <br> This is free software: you are free to change and redistribute it. There is NO WARRANTY, to the extent permitted by law.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>cksum</strong>(1)</p><p><br> Full documentation &lt;<a href="https://www.gnu.org/software/coreutils/md5sum%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/md5sum\\</a>&gt; <br> or available locally via: info &#39;(coreutils) md5sum invocation&#39;</p>',23);function m(e,h,c,g,u,p){return a(),r("div",null,[s("h1",i,n(e.$params.man),1),l])}const w=t(d,[["render",m]]);export{b as __pageData,w as default};
